CURLcode close_curl_easy_handle(struct Curl_easy *data) {
    if (!data) {
        return CURLE_OK;
    }

    /* Clear timers */
    Curl_clrtimeout(data);

    /* Detach from multi handle if part of one */
    if (data->multi) {
        Curl_remove_handle(data->multi, data);
    }

    /* Clean up multi handle if it was created */
    if (data->multi_internal) {
        Curl_multi_clean(data->multi_internal);
        free(data->multi_internal);
    }

    /* Destroy timeout list */
    Curl_safefree(data->state.timeoutlist);

    /* Free memory for states and configurations */
    Curl_safefree(data->set.str[STRING_SSL_EAY_CRLFILE]);
    Curl_safefree(data->set.str[STRING_SSL_ISSUERCERT]);
    Curl_safefree(data->set.str[STRING_SSL_PINNEDPUBLICKEY]);

    /* Close SSL sessions */
    Curl_ssl_close(data);

    /* Clean up redirect information */
    Curl_safefree(data->easy.str[STRING_REDIRECT_URL]);
    Curl_safefree(data->easy.str[STRING_POSTREDIR_URL]);

    /* Clean up share and wildcard structures */
    if (data->share) {
        Curl_share_cleanup(data->share);
    }

    if (data->wildcard) {
        Curl_wildcard_dtor(data->wildcard);
    }

    /* Free the easy handle itself */
    Curl_free(data);

    return CURLE_OK;
}

CURLcode curl_easy_cleanup(struct Curl_easy *data) {
  if (!data)
    return CURLE_OK;

  /* Clear timers and detach from a multi handle if applicable */
  Curl_rem_time(data);
  if (data->multi)
    Curl_multi_remove_handle(data->multi, data);

  /* Clean up any associated multi handles and destroy timeout lists */
  Curl_metalink_free(data);
  Curl_mprintf_free(data);

  /* Free allocated memory for states and configurations */
  Curl_safefree(data->state.path);
  Curl_safefree(data->change.postfields);
  Curl_safefree(data->set.str[STRING_COOKIEJAR]);

  /* Close SSL sessions */
  Curl_ssl_close(data);

  /* Clean up redirect information */
  Curl_cleanup_single(data);

  /* Release resources related to the share and wildcard structures */
  if (data->share)
    Curl_share_detach(data->share, data);

  if (data->wildcard)
    Curl_wildcard_dtor(data->wildcard);

  /* Free the easy handle itself */
  free(data);

  return CURLE_OK;
}

CURLcode Curl_close(struct Curl_easy *data) {
  if(!data)
    return CURLE_OK;

  /* Clear timers and detach from multi handle if needed */
  Curl_cleanup_timer(data);
  if(data->multi)
    Curl_remove_handle(data->multi, data);

  /* Clean up any associated multi handles */
  Curl_mcleanups(data);

  /* Destroy timeout list */
  Curl_timeout_list_free(data);

  /* Free allocated memory */
  Curl_safefree(data->state);
  Curl_safefree(data->wildcard);
  Curl_safefree(data->set);
  Curl_safefree(data->progress);
  Curl_safefree(data->info);
  Curl_safefree(data->url);
  Curl_safefree(data->postfields);
  Curl_safefree(data->httpheader);
  Curl_safefree(data->quote);
  Curl_safefree(data->prequote);
  Curl_safefree(data->postquote);
  Curl_safefree(data->referer);
  Curl_safefree(data->userpwd);
  Curl_safefree(data->user);
  Curl_safefree(data->passwd);
  Curl_safefree(data->proxyuserpwd);
  Curl_safefree(data->proxyuser);
  Curl_safefree(data->proxypasswd);

  /* Close SSL sessions */
  Curl_ssl_close(data);

  /* Clean up redirect information */
  Curl_clean redirected_url(data);

  /* Release resources related to the share and wildcard structures */
  if(data->share)
    Curl_share_unref(data->share);
  Curl_wildcard_dtor(data);

  /* Free the easy handle */
  Curl_safefree(data);

  return CURLE_OK;
}

CURLcode Curl_close(struct Curl_easy *data) {
  if(!data)
    return CURLE_OK;

  /* Clear timers */
  Curl_remtime(data);

  /* Detach from a multi handle if part of one */
  if(data->multi)
    Curl_remove_handle(data->multi, data);

  /* Clean up any associated multi handles */
  if(data->multi)
    Curl_multi_forms(data->multi);

  /* Destroy timeout list */
  Curl_timeout_list_free(data);

  /* Free allocated memory for states and configurations */
  Curl_safefree(data->set.str[STRING_COOKIE_FILE]);
  Curl_safefree(data->set.str[STRING_COOKIEJAR]);
  Curl_safefree(data->set.str[STRING_USERPWD]);
  Curl_safefree(data->set.str[STRING_PROXY]);
  Curl_safefree(data->set.str[STRING_OPTIONS]);
  Curl_safefree(data->set.str[STRING_USERAGENT]);
  Curl_safefree(data->set.str[STRING_REFERER]);
  Curl_safefree(data->set.str[STRING_RTPROTO]);
  Curl_safefree(data->set.str[STRING_RTPORT]);
  Curl_safefree(data->set.str[STRING_RTSP_TRANSPORT]);

  /* Close SSL sessions */
  Curl_ssl_close(data);

  /* Clean up redirect information */
  Curl_safefree(data->urlbuffer);
  Curl_safefree(data->state.up.path);

  /* Clean up share resources */
  if(data->share)
    Curl_share_close(data, data->share);

  /* Clean up wildcard structures */
  Curl_wildcard_dtor(data);

  /* Free the easy handle itself */
  free(data);

  return CURLE_OK;
}

CURLcode close_curl_easy_handle(struct Curl_easy *data) {
    if (!data) {
        return CURLE_OK;
    }

    /* Clear any timers associated with the handle */
    Curl_cleanup_timeout(data);

    /* Detach from a multi handle if part of one */
    if (data->multi) {
        Curl_multi_remove_handle(data->multi, data);
    }

    /* Clean up any associated multi handles */
    Curl_cleanup_multi_handle(data);

    /* Destroy timeout lists */
    Curl_safefree(data->timeouts);

    /* Free allocated memory for states and configurations */
    Curl_safefree(data->state.buffer);
    Curl_safefree(data->set.buffer);
    Curl_safefree(data->wildcard);

    /* Close SSL sessions */
    Curl_ssl_close(data);

    /* Clean up redirect information */
    Curl_safefree(data->change.url);
    Curl_safefree(data->change.ref);
    Curl_safefree(data->change.location);

    /* Clean up share structure */
    if (data->share) {
        Curl_share_close(data->share);
    }

    /* Free the easy handle */
    Curl_safefree(data);

    return CURLE_OK;
}
